import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer tokens = new StringTokenizer("");

    static String next() throws IOException {
        while (!tokens.hasMoreTokens()) {
            tokens = new StringTokenizer(in.readLine());
        }
        return tokens.nextToken();
    }

    public static void main(String[] args) throws IOException {
        long n = Long.parseLong(next());
        long[][] cost = new long[(int) n][3];
        for (int i = 0; i < cost.length; i++) {
            for (int j = 0; j < cost[i].length; j++) {
                cost[i][j] = Long.parseLong(next());
            }
        }

        long a = cost[0][0], b = cost[0][1], c = cost[0][2];
        for (int i = 1; i < n; i++) {
            long na = cost[i][0] + Math.min(b, c);
            long nb = cost[i][1] + Math.min(a, c);
            long nc = cost[i][2] + Math.min(a, b);
            a = na;
            b = nb;
            c = nc;
        }
        System.out.println(Math.min(a, Math.min(b, c)));
    }
}
